import { AUTH_CSRF_HEADER, AUTH_SESSION_COOKIE, readCsrfToken } from "@skillplane/auth";
import { DomainError } from "@skillplane/domain";
import type { MiddlewareHandler } from "hono";
import type { ApiEnvironment, ApiServiceProvider } from "../context.js";
import { authenticateServicePrincipalRequest } from "../service-principal-auth.js";
import { ensurePersonalWorkspace } from "../tenancy.js";

const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

export function enforceCookieCsrf(
  request: Request,
  hasSession: boolean,
  hasServicePrincipal: boolean,
): void {
  const url = new URL(request.url);
  if (
    !hasSession ||
    hasServicePrincipal ||
    SAFE_METHODS.has(request.method) ||
    !url.pathname.startsWith("/api/v1/")
  ) {
    return;
  }
  const cookie = request.headers.get("cookie") ?? "";
  const bearerWithoutSessionCookie =
    request.headers.get("authorization")?.startsWith("Bearer ") === true &&
    !cookie
      .split(";")
      .some((entry) => entry.trim().startsWith(`${AUTH_SESSION_COOKIE}=`));
  if (bearerWithoutSessionCookie) return;
  const cookieToken = readCsrfToken(request.headers.get("cookie"));
  const headerToken = request.headers.get(AUTH_CSRF_HEADER);
  if (!cookieToken || !headerToken || cookieToken !== headerToken) {
    throw new DomainError(
      "AUTH_CSRF_INVALID",
      "The request could not be verified",
      403,
    );
  }
}

export function authenticationMiddleware(
  getServices?: ApiServiceProvider,
): MiddlewareHandler<ApiEnvironment> {
  return async (context, next) => {
    if (!getServices || context.req.path.startsWith("/api/v1/health/")) {
      context.set("services", null);
      context.set("session", null);
      context.set("servicePrincipal", null);
      await next();
      return;
    }
    const services = await getServices(context.env);
    try {
      context.set("services", services);
      const serviceAuthentication = await authenticateServicePrincipalRequest(
        context.req.raw,
        services,
      );
      const servicePrincipal = serviceAuthentication?.principal ?? null;
      context.set("servicePrincipal", servicePrincipal);
      const session = servicePrincipal
        ? null
        : await services.auth.provider.authenticate(context.req.raw);
      context.set("session", session);
      if (session) {
        await ensurePersonalWorkspace(services.database.pool, session);
      }
      enforceCookieCsrf(context.req.raw, Boolean(session), Boolean(servicePrincipal));
      await next();
    } finally {
      try {
        await getServices.release?.(services);
      } catch {
        console.error(
          JSON.stringify({
            component: "api",
            event: "api.services.release.failed",
          }),
        );
      }
    }
  };
}
import {
  parseRuntimeConfig,
  safeConfigDiagnostic,
  type RuntimeBindings,
} from "@skillplane/config";
import pg from "pg";

const { Client } = pg;

export interface HealthCheck {
  readonly ok: boolean;
  readonly code: string;
  readonly latencyMs: number;
}

export interface ReadinessResult {
  readonly ok: boolean;
  readonly checks: {
    readonly configuration: HealthCheck;
    readonly postgres: HealthCheck;
    readonly objectStorage: HealthCheck;
  };
}

export type ReadinessProbe = (bindings: RuntimeBindings) => Promise<ReadinessResult>;

function elapsed(startedAt: number): number {
  return Math.max(0, Math.round(performance.now() - startedAt));
}

async function withTimeout<T>(
  operation: Promise<T>,
  timeoutMilliseconds: number,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_resolve, reject) => {
    timeoutHandle = setTimeout(
      () => reject(new Error("HEALTH_CHECK_TIMEOUT")),
      timeoutMilliseconds,
    );
  });

  try {
    return await Promise.race([operation, timeout]);
  } finally {
    if (timeoutHandle !== undefined) {
      clearTimeout(timeoutHandle);
    }
  }
}

export function createReadinessProbe(options?: {
  readonly timeoutMilliseconds?: number;
}): ReadinessProbe {
  const timeoutMilliseconds = options?.timeoutMilliseconds ?? 2_500;

  return async (bindings) => {
    const configurationStartedAt = performance.now();
    let config;
    try {
      config = parseRuntimeConfig(bindings);
    } catch (error) {
      const diagnostic = safeConfigDiagnostic(error);
      const blocked = {
        ok: false,
        code: "CHECK_BLOCKED",
        latencyMs: 0,
      } as const;
      return {
        ok: false,
        checks: {
          configuration: {
            ok: false,
            code: diagnostic.code,
            latencyMs: elapsed(configurationStartedAt),
          },
          postgres: blocked,
          objectStorage: blocked,
        },
      };
    }

    const configuration: HealthCheck = {
      ok: true,
      code: "CONFIG_VALID",
      latencyMs: elapsed(configurationStartedAt),
    };

    const postgresStartedAt = performance.now();
    const postgresCheck = withTimeout(
      (async (): Promise<HealthCheck> => {
        const client = new Client({
          connectionString: config.database.connectionString,
          connectionTimeoutMillis: timeoutMilliseconds,
          query_timeout: timeoutMilliseconds,
        });
        try {
          await client.connect();
          await client.query("select 1 as ready");
          return {
            ok: true,
            code: "POSTGRES_READY",
            latencyMs: elapsed(postgresStartedAt),
          };
        } finally {
          await client.end().catch(() => undefined);
        }
      })(),
      timeoutMilliseconds,
    ).catch((): HealthCheck => ({
      ok: false,
      code: "POSTGRES_UNAVAILABLE",
      latencyMs: elapsed(postgresStartedAt),
    }));

    const objectStorageStartedAt = performance.now();
    const objectStorageCheck = withTimeout(
      config.objectStorage.list({ limit: 1 }).then((): HealthCheck => ({
        ok: true,
        code: "R2_READY",
        latencyMs: elapsed(objectStorageStartedAt),
      })),
      timeoutMilliseconds,
    ).catch((): HealthCheck => ({
      ok: false,
      code: "R2_UNAVAILABLE",
      latencyMs: elapsed(objectStorageStartedAt),
    }));

    const [postgres, objectStorage] = await Promise.all([
      postgresCheck,
      objectStorageCheck,
    ]);

    return {
      ok: postgres.ok && objectStorage.ok,
      checks: {
        configuration,
        postgres,
        objectStorage,
      },
    };
  };
}
