  async fetch(
    request: Request,
    env: AccountWorkerEnv,
    ctx?: ExecutionContext
  ): Promise<Response> {
    (globalThis as typeof globalThis & { ctx?: ExecutionContext }).ctx = ctx;
    const globalProcess = globalThis as unknown as {
