          outcome: lookup.continueLocally ? 'local' : 'redirect',
          metadata: {
            identifier: lookup.identifier,
            authority: lookup.authority,
            continueLocally: lookup.continueLocally
          }
        });

        return jsonSuccess(request, lookup);
      }
    },
