  const result = spawnSync(command, args, {
    cwd: serviceRoot,
    stdio: 'inherit',
    env: process.env,
    shell: process.platform === 'win32'
  });
  if (result.status !== 0) {
    process.exit(result.status ?? 1);
  }
}

function normalizeEnvironment(value) {
