          {/if}

          <button
            class="primary"
            type="submit"
            disabled={code.length !== 6 ||
              ["verifying", "success", "expired"].includes(verifyState.kind)}
          >
            {verifyState.kind === "verifying" ? "Verifying…" : "Verify and continue"}
            <ArrowRight size={17} weight="bold" aria-hidden="true" />
          </button>
