import {
  authFnApiKeyPlugin,
  authFnEmailOtpPlugin,
  authFnMultiRegionPlugin,
  authFnNativeHandoffPlugin,
  authFnPasswordPlugin,
  authFnSocialOAuthPlugin,
  authFnTwoFactorPlugin,
  createAuthFn,
  type AuthFnEvent,
  type AuthFnConfig,
  type AuthFnDeliveryProvider,
  type AuthFnMultiRegionRegionConfig,
  type AuthFnRegionLookupStore,
  type AuthFnSocialProviderConfig,
  type SocialOAuthPluginConfig
} from '@authfn/core';
import type { Adapter, KVStoreAdapter } from '@superfunctions/db';
import type { Logger } from '@logfn/core';
import { createAccountLookupStore } from './lookup/dynamodb.js';
import { createAuthSecurityEmitter } from './security/events.js';
import { nucleusLifecyclePlugin } from './plugins/nucleus-lifecycle.js';
import { nucleusWidgetTokenPlugin } from './plugins/widget-token.js';
import { ACCOUNT_AUTH_NAMESPACE } from './db/schema.js';
import { sendAccountDebugLog } from './debug-sink.js';

export interface CreateAccountAuthInput {
  database: Adapter;
  cacheStore: KVStoreAdapter;
  delivery: AuthFnDeliveryProvider;
  logger: Logger;
  regions?: AuthFnMultiRegionRegionConfig[];
  lookupStore?: AuthFnRegionLookupStore;
  oauthProviders?: Partial<Record<'google' | 'apple', AuthFnSocialProviderConfig | undefined>>;
  oauthPlugin?: Omit<SocialOAuthPluginConfig, 'providers'>;
  securityEventSink?: (event: AuthFnEvent) => Promise<void> | void;
}

export function createAccountAuth(input: CreateAccountAuthInput) {
  const regions = input.regions ?? resolveRegions();
  const defaultRegion = regions[0];
  const oauthProviders = input.oauthProviders ?? resolveOAuthProviders();
  const config: AuthFnConfig = {
    database: input.database,
    cacheStore: input.cacheStore,
    namespace: process.env.AUTHFN_NAMESPACE ?? ACCOUNT_AUTH_NAMESPACE,
    basePath: '/auth',
    cookie: {
      prefix: process.env.AUTHFN_COOKIE_PREFIX ?? 'nucleus',
      sameSite: 'lax',
      secure: resolveCookieSecure(defaultRegion.authority)
    },
    accountLinking: {
      oauthByVerifiedEmail: {
        providers: ['google', 'apple'],
        requireExistingEmailVerified: true,
        requireProviderEmailVerified: true
      },
      otpSignUpExistingUser: true,
      passwordForAuthenticatedUser: {
        requireExistingEmailVerified: true
      }
    },
    runtime: {
      resolve(request) {
        const url = new URL(request.url);
        const matched = regions.find((region) =>
          [new URL(region.authority).hostname, ...(region.hosts ?? [])]
            .some((host) => host === url.hostname || url.hostname.endsWith(`.${host}`))
        ) ?? defaultRegion;

        return {
          issuer: matched.authority,
          baseUrl: matched.baseUrl ?? matched.authority,
          regionId: matched.regionId,
          cookie: matched.cookie,
          oauth: matched.oauth
        };
      }
    },
    observability: {
      emit: input.securityEventSink ?? createAuthSecurityEmitter(input.logger)
    },
    plugins: [
      authFnPasswordPlugin({
        otp: {
          delivery: input.delivery
        }
      }),
      authFnEmailOtpPlugin({
        delivery: input.delivery
      }),
      authFnSocialOAuthPlugin({
        ...input.oauthPlugin,
        fetcher: input.oauthPlugin?.fetcher ?? createOAuthDiagnosticFetcher(input.logger),
        providers: oauthProviders
      }),
      authFnTwoFactorPlugin({
        issuer: process.env.AUTHFN_2FA_ISSUER ?? 'Nucleus'
      }),
      authFnApiKeyPlugin(),
      authFnMultiRegionPlugin({
        regions,
        defaultRegionId: defaultRegion.regionId,
        lookupStore: input.lookupStore ?? createAccountLookupStore()
      }),
      authFnNativeHandoffPlugin(),
      nucleusLifecyclePlugin(),
      nucleusWidgetTokenPlugin()
    ],
    openApi: {
      title: 'Nucleus Account API',
      version: '2026-04-24'
    }
  };

  return createAuthFn(config);
}

function resolveCookieSecure(authority: string): boolean {
  const explicit = readBoolean(process.env.AUTHFN_COOKIE_SECURE);
  if (explicit !== undefined) {
    return explicit;
  }

  try {
    return new URL(authority).protocol === 'https:';
  } catch {
    return process.env.NODE_ENV === 'production';
  }
}

function readBoolean(value: string | undefined): boolean | undefined {
  if (value === undefined) {
    return undefined;
  }
  const normalized = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(normalized)) {
    return true;
  }
  if (['0', 'false', 'no', 'off'].includes(normalized)) {
    return false;
  }
  return undefined;
}

function resolveRegions(): AuthFnMultiRegionRegionConfig[] {
  const raw = process.env.ACCOUNT_REGIONS_JSON;
  if (raw) {
    return JSON.parse(raw) as AuthFnMultiRegionRegionConfig[];
  }

  const authority = process.env.ACCOUNT_AUTHORITY ?? 'http://127.0.0.1:8787';
  const domain = process.env.ACCOUNT_COOKIE_DOMAIN;
  return [
    {
      regionId: process.env.ACCOUNT_REGION_ID ?? 'local',
      authority,
      hosts: [new URL(authority).hostname],
      domain,
      cookie: domain ? { domain } : undefined,
      oauth: {
        google: optionalOAuthProvider('GOOGLE'),
        apple: optionalOAuthProvider('APPLE')
      }
    }
  ];
}

function resolveOAuthProviders() {
  return {
    google: optionalOAuthProvider('GOOGLE'),
    apple: optionalOAuthProvider('APPLE')
  };
}

function optionalOAuthProvider(prefix: 'GOOGLE' | 'APPLE') {
  const clientId = process.env[`${prefix}_OAUTH_CLIENT_ID`];
  if (!clientId) {
    return undefined;
  }

  const configuredReturnTo = readCsv(process.env[`${prefix}_OAUTH_RETURN_TO`]);
  const providerReturnTo = withNativeOAuthReturnTargets(configuredReturnTo);
  const fallbackReturnTo = withNativeOAuthReturnTargets(readCsv(process.env.ACCOUNT_CORS_ORIGINS));
  const appleClientSecretResolver = prefix === 'APPLE'
    ? createAppleClientSecretResolver(clientId)
    : undefined;

  return {
    clientId,
    ...(appleClientSecretResolver
      ? { clientSecretResolver: appleClientSecretResolver }
      : { clientSecret: process.env[`${prefix}_OAUTH_CLIENT_SECRET`] }),
    allowlistedRedirectUris: readCsv(process.env[`${prefix}_OAUTH_REDIRECT_URIS`]),
    allowlistedReturnTo: configuredReturnTo.length > 0 ? providerReturnTo : fallbackReturnTo,
    ...(prefix === 'APPLE'
      ? { nativeClientIds: resolveAppleNativeClientIds() }
      : {}),
    scopes: prefix === 'GOOGLE' ? ['openid', 'email', 'profile'] : ['name', 'email']
  };
}

function resolveAppleNativeClientIds(): string[] {
  const configured = readCsv(process.env.APPLE_OAUTH_NATIVE_CLIENT_IDS);
  if (configured.length > 0) {
    return configured;
  }
  return ['io.nucleum', 'io.memotron', 'io.pointron'];
}

function withNativeOAuthReturnTargets(values: string[]): string[] {
  return Array.from(new Set([...values, ...nativeOAuthReturnTargets()]));
}

function nativeOAuthReturnTargets(): string[] {
  return ['nucleum', 'memotron', 'pointron'].map((scheme) => `${scheme}://oauthsignin`);
}

function readCsv(value: string | undefined): string[] {
  return (value ?? '')
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function createOAuthDiagnosticFetcher(
  logger: Logger
): NonNullable<SocialOAuthPluginConfig['fetcher']> {
  return async (url, init) => {
    const response = await fetch(url, {
      method: init.method,
      headers: init.headers,
      body: init.body
    });
    const rawBody = await response.text();
    const provider = resolveOAuthTokenProvider(url);
    if (provider && (!response.ok || process.env.AUTHFN_OAUTH_DEBUG === 'true')) {
      const payload = {
        provider,
        request: summarizeOAuthTokenRequest(provider, init.body),
        response: summarizeOAuthTokenResponse(response.status, rawBody)
      };
      logger.info(`${provider} oauth token exchange`, {
        request: payload.request,
        response: payload.response
      });
      sendAccountDebugLog({
        level: response.ok ? 'info' : 'warn',
        message: `${provider} oauth token exchange`,
        payload,
        tags: ['authfn', 'oauth', provider, 'token-exchange']
      });
    }

    return {
      ok: response.ok,
      status: response.status,
      headers: {
        get(name: string) {
          return response.headers.get(name);
        }
      },
      async text() {
        return rawBody;
      }
    };
  };
}

function resolveOAuthTokenProvider(url: string): 'apple' | 'google' | undefined {
  if (url === 'https://appleid.apple.com/auth/token') {
    return 'apple';
  }
  if (url === 'https://oauth2.googleapis.com/token') {
    return 'google';
  }
  return undefined;
}

function summarizeOAuthTokenRequest(provider: 'apple' | 'google', body: string | undefined) {
  return provider === 'apple'
    ? summarizeAppleTokenRequest(body)
    : summarizeGoogleTokenRequest(body);
}

function summarizeGoogleTokenRequest(body: string | undefined) {
  const params = new URLSearchParams(body ?? '');
  return {
    grantType: params.get('grant_type'),
    clientId: params.get('client_id'),
    redirectUri: params.get('redirect_uri'),
    code: summarizeOAuthCode(params.get('code')),
    hasCodeVerifier: Boolean(params.get('code_verifier')),
    hasClientSecret: Boolean(params.get('client_secret'))
  };
}

function summarizeAppleTokenRequest(body: string | undefined) {
  const params = new URLSearchParams(body ?? '');
  const clientSecret = params.get('client_secret') ?? undefined;
  return {
    grantType: params.get('grant_type'),
    clientId: params.get('client_id'),
    redirectUri: params.get('redirect_uri'),
    code: summarizeOAuthCode(params.get('code')),
    hasCodeVerifier: Boolean(params.get('code_verifier')),
    clientSecret: summarizeJwt(clientSecret)
  };
}

function summarizeOAuthCode(value: string | null) {
  if (!value) {
    return { present: false };
  }

  return {
    present: true,
    length: value.length,
    hasWhitespace: /\s/.test(value),
    hasPlus: value.includes('+'),
    hasSlash: value.includes('/'),
    hasEquals: value.includes('='),
    startsWithExpectedPrefix: value.startsWith('c')
  };
}

function summarizeOAuthTokenResponse(status: number, rawBody: string) {
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    parsed = new URLSearchParams(rawBody);
  }

  if (parsed instanceof URLSearchParams) {
    return {
      status,
      error: parsed.get('error'),
      errorDescription: parsed.get('error_description')
    };
  }

  if (!parsed || typeof parsed !== 'object') {
    return { status };
  }

  const record = parsed as Record<string, unknown>;
  return {
    status,
    error: typeof record.error === 'string' ? record.error : undefined,
    errorDescription:
      typeof record.error_description === 'string'
        ? record.error_description
        : undefined,
    hasIdToken: typeof record.id_token === 'string',
    hasAccessToken: typeof record.access_token === 'string'
  };
}

import fs from 'node:fs';
import path from 'node:path';

export function renderWranglerConfig(serviceRoot, config, environment, options = {}) {
  const includeRoutes = options.includeRoutes === true;
  const outputDir = path.join(serviceRoot, '.wrangler');
  fs.mkdirSync(outputDir, { recursive: true });
  const generatedConfig = {
    ...config,
    main: toPosixPath(path.relative(outputDir, path.join(serviceRoot, config.main ?? 'dist/worker.js')))
  };
  const source = renderConfig(generatedConfig, environment, { includeRoutes });
  const suffix = includeRoutes ? 'with-routes' : 'deploy';
  const outputPath = path.join(outputDir, `wrangler.${environment}.${suffix}.toml`);
  fs.writeFileSync(outputPath, source);
  return outputPath;
}

export function renderConfig(config, environment, options = {}) {
  const includeRoutes = options.includeRoutes === true;
  const envConfig = readEnvironment(config, environment);
  const lines = [
    kv('name', config.workerNamePrefix ?? 'nucleus-account'),
    kv('main', config.main ?? 'dist/worker.js'),
    kv('compatibility_date', config.compatibilityDate ?? '2026-04-24'),
    array('compatibility_flags', config.compatibilityFlags ?? ['nodejs_compat']),
    kv('workers_dev', true),
    '',
    '[vars]',
    kv('NODE_ENV', 'production'),
    ''
  ];

  for (const lookupEnv of lookupEnvironments(config, environment)) {
    lines.push(...renderLookupEnvironment(config, lookupEnv), '');
  }

  for (const regionId of Object.keys(config.regions)) {
    if (!envConfig.regions[regionId]) continue;
    lines.push(...renderRegionalEnvironment(config, environment, regionId, { includeRoutes }), '');
  }

  return `${lines.join('\n').trimEnd()}\n`;
}

export function routeDefinitions(config, environment, regions = Object.keys(config.regions)) {
  const envConfig = readEnvironment(config, environment);
  return regions.flatMap((regionId) => {
    const regionConfig = envConfig.regions[regionId];
    if (!regionConfig) {
      throw new Error(`Unknown ${environment} region: ${regionId}`);
    }
    return productDomains(config).map((domain) => ({
      pattern: `${accountHost(config, environment, regionId, domain)}/*`,
      script: workerName(config, environment, regionId),
      zoneName: domain
    }));
  });
}

export function missingHyperdriveIds(config, environment, regions) {
  const envConfig = readEnvironment(config, environment);
  const missing = [];
  for (const region of regions) {
    const regionConfig = envConfig.regions[region];
    if (!regionConfig) {
      missing.push(`${environment}/${region}: missing region config`);
      continue;
    }
    const value = resolveHyperdriveId(environment, region, regionConfig.hyperdriveId);
    if (isPlaceholder(value)) {
      missing.push(`${environment}/${region}: set ${hyperdriveOverrideName(environment, region, regionConfig.hyperdriveId)} or update services/account/config/environments.json`);
    }
  }
  return missing;
}

export function resolveHyperdriveId(environment, region, configuredValue) {
  const overrideName = hyperdriveOverrideName(environment, region, configuredValue);
  return process.env[overrideName]?.trim() || configuredValue;
}

function renderLookupEnvironment(config, lookupEnv) {
  const name = lookupEnv.workerName ?? `${config.workerNamePrefix}-${lookupEnv.id}`;
  return [
    header(`env.${lookupEnv.id}`),
    kv('name', name),
    kv('workers_dev', false),
    '',
    header(`env.${lookupEnv.id}.vars`),
    kv('NODE_ENV', 'production'),
    '',
    arrayHeader(`env.${lookupEnv.id}.durable_objects.bindings`),
    kv('name', 'AUTHFN_REGION_LOOKUP'),
    kv('class_name', 'AuthFnRegionLookupDurableObject'),
    '',
    arrayHeader(`env.${lookupEnv.id}.migrations`),
    kv('tag', 'v1-authfn-region-lookup'),
    array('new_sqlite_classes', ['AuthFnRegionLookupDurableObject'])
  ]…545 tokens truncated…r (const [provider, redirectUris] of oauthRedirectUris) {
    lines.push(kv(`${provider.toUpperCase()}_OAUTH_REDIRECT_URIS`, redirectUris));
    lines.push(kv(`${provider.toUpperCase()}_OAUTH_RETURN_TO`, oauthReturnTo.join(',')));
  }

  lines.push('');
  if (region.placementRegion) {
    lines.push(header(`env.${wranglerEnv}.placement`));
    lines.push(kv('mode', 'targeted'));
    lines.push(kv('region', region.placementRegion));
    lines.push('');
  }

  if (options.includeRoutes) {
    for (const domain of productDomains(config)) {
      lines.push(arrayHeader(`env.${wranglerEnv}.routes`));
      lines.push(kv('pattern', `${accountHost(config, environment, regionId, domain)}/*`));
      lines.push(kv('zone_name', domain));
      lines.push('');
    }
  }

  lines.push(arrayHeader(`env.${wranglerEnv}.hyperdrive`));
  lines.push(kv('binding', 'ACCOUNT_DB'));
  lines.push(kv('id', resolveHyperdriveId(environment, regionId, regionConfig.hyperdriveId)));
  lines.push('');
  lines.push(arrayHeader(`env.${wranglerEnv}.kv_namespaces`));
  lines.push(kv('binding', 'ACCOUNT_CACHE'));
  lines.push(kv('id', envConfig.cacheKvNamespaceId));
  lines.push(kv('remote', true));
  lines.push('');
  lines.push(arrayHeader(`env.${wranglerEnv}.durable_objects.bindings`));
  lines.push(kv('name', 'AUTHFN_REGION_LOOKUP'));
  lines.push(kv('class_name', 'AuthFnRegionLookupDurableObject'));
  lines.push(kv('script_name', envConfig.lookupWorkerName));
  const secretsStoreBindings = secretStoreBindingsForEnvironment(config, environment);
  for (const binding of secretsStoreBindings) {
    lines.push('');
    lines.push(arrayHeader(`env.${wranglerEnv}.secrets_store_secrets`));
    lines.push(kv('binding', binding.binding));
    lines.push(kv('store_id', binding.storeId));
    lines.push(kv('secret_name', binding.secretName));
  }
  return lines;
}

export function secretStoreBindingsForEnvironment(config, environment) {
  const storeId = config.secretsStore?.storeId;
  const names = config.secretsStore?.names ?? {};
  if (!storeId) return [];
  return Object.entries(names).map(([binding, template]) => ({
    binding,
    storeId,
    secretName: renderSecretName(template, environment)
  }));
}

function renderSecretName(template, environment) {
  return String(template).replaceAll('{ENV}', environment.toUpperCase());
}

function lookupEnvironments(config, selectedEnvironment) {
  const selected = readEnvironment(config, selectedEnvironment);
  const entries = new Map();
  for (const [environment, envConfig] of Object.entries(config.environments)) {
    if (environment !== selectedEnvironment && envConfig.lookupWorkerEnv !== selected.lookupWorkerEnv) {
      continue;
    }
    entries.set(envConfig.lookupWorkerEnv, {
      id: envConfig.lookupWorkerEnv,
      workerName: envConfig.lookupWorkerName
    });
  }
  return [...entries.values()];
}

function webOrigins(config, environment, envConfig) {
  const origins = productDomains(config).map((domain) => `https://${envConfig.webSubdomain}.${domain}`);
  if (envConfig.includeLocalWebOrigins && environment !== 'local') {
    origins.push(...productDomains(config).map((domain) => `https://local.${domain}`));
  }
  origins.push('tauri://localhost');
  return origins;
}

function productDomains(config) {
  return Array.from(new Set(Object.values(config.productDomains ?? { default: config.accountDomain }).filter(Boolean)));
}

function accountAuthority(config, environment, regionId, domain = config.accountDomain) {
  return `https://${accountHost(config, environment, regionId, domain)}`;
}

function accountHost(config, environment, regionId, domain = config.accountDomain) {
  const envConfig = readEnvironment(config, environment);
  const suffix = envConfig.urlSegment ? `-${envConfig.urlSegment}` : '';
  return `account-${regionId}${suffix}.${domain}`;
}

function cookieDomainForProductDomain(domain) {
  return `.${domain.replace(/^\./, '')}`;
}

function workerName(config, environment, regionId) {
  return `${config.workerNamePrefix}-${environment}-${regionId}`;
}

function readEnvironment(config, environment) {
  const envConfig = config.environments[environment];
  if (!envConfig) {
    throw new Error(`Unknown account service environment: ${environment}`);
  }
  return envConfig;
}

function hyperdriveOverrideName(environment, region, configuredValue) {
  if (configuredValue?.startsWith('TODO_') || configuredValue?.startsWith('REPLACE_')) {
    return configuredValue;
  }
  return `ACCOUNT_${environment}_${region}_HYPERDRIVE_ID`
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '_');
}

function isPlaceholder(value) {
  return !value || value.startsWith('TODO_') || value.startsWith('REPLACE_');
}

function header(name) {
  return `[${name}]`;
}

function arrayHeader(name) {
  return `[[${name}]]`;
}

function kv(key, value) {
  if (typeof value === 'boolean') return `${key} = ${value}`;
  return `${key} = ${JSON.stringify(String(value))}`;
}

function array(key, values) {
  return `${key} = [${values.map((value) => JSON.stringify(String(value))).join(', ')}]`;
}

function toPosixPath(value) {
  return value.split(path.sep).join('/');
}
import {
  createAuthFnRegionalClient,
  type AuthFnCachedRegion,
  type AuthFnClientRequestMetric,
  type AuthFnRegionalClient,
  type AuthFnRegionStorage
} from "@authfn/client";
import { clientStorage } from "@21n/persistence/persistence.utils";
import { ClientStorageKey } from "@21n/persistence/persistence.type";
import { resolveAccountBaseUrl, resolveAccountCookiePrefix } from "../network";
import { logger } from "@21n/components/debug/logger.client";
import { isExtensionEnvironment } from "@21n/utils/browser.utils";

type StoredRegionValue = string | AuthFnCachedRegion;

const authClientsMap: Map<string, AuthFnRegionalClient> = new Map();
const REGION_CACHE_TTL_MS = 15 * 60 * 1000;

export const authClient = async (params?: {
  region?: string;
  isPreventCachedInstance?: boolean;
}): Promise<AuthFnRegionalClient> => {
  const region =
    params?.region ??
    (await clientStorage.get(ClientStorageKey.REGION)) ??
    "insouth";
  const cacheKey = "regional";
  if (authClientsMap.has(cacheKey) && !params?.isPreventCachedInstance) {
    const existing = authClientsMap.get(cacheKey) as AuthFnRegionalClient;
    existing.setCurrentRegionId(region);
    return existing;
  }

  const client = createAuthFnRegionalClient({
    defaultRegionId: region,
    resolveBaseUrl: resolveAuthFnBaseUrl,
    storage: createNucleusRegionStorage(),
    cacheTtlMs: REGION_CACHE_TTL_MS,
    clientOptions: {
      cookiePrefix: resolveAccountCookiePrefix(region),
      credentials: "include",
      bearerToken: shouldUseAuthFnBearerSession()
        ? async () =>
            (await clientStorage.get(ClientStorageKey.AUTHFN_TOKEN)) ?? undefined
        : undefined,
      onRequestMetric: emitAccountNetworkMetric
    },
    onRegionChanged: async (event) => {
      await clientStorage.set(ClientStorageKey.REGION, event.toRegionId);
    }
  });
  client.setCurrentRegionId(region);
  authClientsMap.set(cacheKey, client);
  return client;
};

export function resolveAuthFnBaseUrl(region: string) {
  return `${resolveAccountBaseUrl(region).replace(/\/$/, "")}/auth`;
}

export function shouldUseAuthFnBearerSession(): boolean {
  if (typeof window === "undefined") return false;
  return import.meta.env?.VITE_NATIVE_EMBED === "true" || isExtensionEnvironment();
}

export function resolveAuthFnSessionMode(): "cookie" | "hybrid" {
  return shouldUseAuthFnBearerSession() ? "hybrid" : "cookie";
}

export async function bootstrapNucleusAccount(region: string) {
  if (!shouldUseAuthFnBearerSession()) {
    return { kind: "not-authfn" as const };
  }
  const token = await clientStorage.get(ClientStorageKey.AUTHFN_TOKEN);
  if (!token) {
    return { kind: "not-authfn" as const };
  }

  try {
    const response = await fetch(`${resolveAuthFnBaseUrl(region)}/nucleus/bootstrap`, {
      method: "POST",
      credentials: "include",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ region })
    });
    const result = await response.json().catch(() => null);
    if (!response.ok || !result?.ok || !result.data?.session) {
      return {
        kind: "failed" as const,
        status: response.status,
        error: result?.error
      };
    }

    return {
      kind: "success" as const,
      token,
      session: result.data.session
    };
  } catch (error) {
    return {
      kind: "failed" as const,
      status: 0,
      error
    };
  }
}

function emitAccountNetworkMetric(metric: AuthFnClientRequestMetric) {
  if (!shouldEmitAccountLatencyMetric()) return;
  logger.debug({
    at: "authfn.account.network",
    method: metric.method,
    path: metric.path,
    status: metric.status,
    ok: metric.ok,
    durationMs: round(metric.durationMs),
    requestId: metric.requestId,
    serverTiming: metric.serverTiming,
    dbDurationMs: metric.dbDurationMs,
    dbCallCount: metric.dbCallCount,
    dbMaxDurationMs: metric.serverTiming?.match(/dbmax;dur=([0-9.]+)/)?.[1],
    cacheDurationMs: metric.cacheDurationMs,
    cacheCallCount: metric.cacheCallCount,
    lookupDurationMs: metric.lookupDurationMs,
    lookupCallCount: metric.lookupCallCount,
    workerColo: metric.workerColo,
    accountRegion: metric.accountRegion,
    error: metric.error
  });
}

function shouldEmitAccountLatencyMetric(): boolean {
  if (import.meta.env?.VITE_ACCOUNT_LATENCY_DEBUG === "true") return true;
  if (typeof window === "undefined") return false;
  return window.localStorage?.getItem("accountLatencyDebug") === "true";
}

function round(value: number): number {
  return Math.round(value * 100) / 100;
}

export async function performSessionCheck(): Promise<boolean | undefined> {
  if (typeof window === "undefined") return false;
  const shouldUseBearerSession = shouldUseAuthFnBearerSession();
  const authFnToken = shouldUseBearerSession
    ? (await clientStorage.get(ClientStorageKey.AUTHFN_TOKEN)) ?? undefined
    : undefined;
  const offlineSessionId =
    (await clientStorage.get(ClientStorageKey.OFFLINE_SESSION_ID)) ?? undefined;
  if (!shouldUseBearerSession) {
    await clientStorage.remove(ClientStorageKey.AUTHFN_TOKEN);
  }

  try {
    const client = await authClient({ isPreventCachedInstance: true });
    const session = await client.getSession();
    if (!session.ok) {
      logger.warn({
        at: "performSessionCheck.session.failed",
        hasAuthFnToken: Boolean(authFnToken),
        hasOfflineSession: Boolean(offlineSessionId),
        error: session.error,
        currentPath: window.location.pathname
      });
      return Boolean(offlineSessionId && !authFnToken);
    }
    if (session.data.session) {
      await clientStorage.set(ClientStorageKey.USER, session.data.session);
      if (session.data.session.primaryEmail) {
        await client.resolveRegion({
          identifier: session.data.session.primaryEmail
        });
      }
    }
    logger.info({
      at: "performSessionCheck.session.result",
      hasAuthFnToken: Boolean(authFnToken),
      hasOfflineSession: Boolean(offlineSessionId),
      hasSession: Boolean(session.data.session),
      regionId: session.data.session?.regionId,
      currentPath: window.location.pathname
    });
    return Boolean(session.data.session) || Boolean(offlineSessionId && !authFnToken);
  } catch (error) {
    logger.error({ at: "performSessionCheck.exception", error });
    return offlineSessionId && !authFnToken ? true : undefined;
  }
}

function createNucleusRegionStorage(): AuthFnRegionStorage {
  return {
    async get(identifier) {
      const map = await readRegionMap();
      const value = map[normalizeIdentifier(identifier)];
      if (!value) return null;
      return typeof value === "string"
        ? regionValueFromLegacyString(identifier, value)
        : value;
    },
    async set(identifier, value) {
      const map = await readRegionMap();
      map[normalizeIdentifier(identifier)] = value;
      await clientStorage.set(ClientStorageKey.USER_REGION_MAP, map);
    },
    async delete(identifier) {
      const map = await readRegionMap();
      delete map[normalizeIdentifier(identifier)];
      await clientStorage.set(ClientStorageKey.USER_REGION_MAP, map);
    }
  };
}

async function readRegionMap(): Promise<Record<string, StoredRegionValue>> {
  const raw = (await clientStorage.get(ClientStorageKey.USER_REGION_MAP)) ?? "{}";
  if (typeof raw === "object" && raw !== null) {
    return raw as Record<string, StoredRegionValue>;
  }
  try {
    return JSON.parse(raw) as Record<string, StoredRegionValue>;
  } catch {
    return {};
  }
}

function regionValueFromLegacyString(
  identifier: string,
  regionId: string
): AuthFnCachedRegion {
  const normalized = normalizeIdentifier(identifier);
  return {
    identifier: normalized,
    regionId,
    authority: resolveAccountBaseUrl(regionId),
    cachedAt: Date.now(),
    expiresAt: Date.now() + REGION_CACHE_TTL_MS
  };
}

function normalizeIdentifier(identifier: string) {
  return identifier.trim().toLowerCase();
}
export function resolveHost() {
  const nativeWebOrigin = resolveNativeConfigUrl("webOrigin");
  if (nativeWebOrigin) return nativeWebOrigin.hostname;

  if (
    typeof window !== "undefined" &&
    (window.location.protocol === "http:" ||
      window.location.protocol === "https:")
  ) {
    return window.location.hostname;
  }
  return (
    import.meta.env?.VITE_HOST ??
    (typeof window !== "undefined" ? window.location.hostname : "localhost")
  );
}

export function resolveAccountBaseUrl(region: string) {
  const nativeAccountBaseUrl = resolveNativeAccountBaseUrl(region);
  if (nativeAccountBaseUrl) {
    return nativeAccountBaseUrl;
  }

  const regionalTemplate = import.meta.env?.VITE_ACCOUNT_BASE_URL_TEMPLATE;
  if (regionalTemplate) {
    return renderAccountBaseUrlTemplate(regionalTemplate, region);
  }

  const explicitBaseUrl = import.meta.env?.VITE_ACCOUNT_BASE_URL;
  if (explicitBaseUrl) {
    return explicitBaseUrl.replace(/\/$/, "");
  }

  const host = resolveHost().toLowerCase();
  if (isLoopbackHost(host)) {
    return "http://localhost:3000";
  }

  const accountEnv = resolveAccountEnvironment(host);
  const accountDomain = resolveAccountDomain(host);
  const normalizedRegion = normalizeAccountRegion(region);
  const envSuffix = accountEnv === "live" ? "" : `-${accountEnv}`;
  return `https://account-${normalizedRegion}${envSuffix}.${accountDomain}`;
}

export function resolveAccountCookiePrefix(region = "insouth") {
  const configured = import.meta.env?.VITE_ACCOUNT_COOKIE_PREFIX?.trim();
  if (configured) return configured;

  const baseUrl = resolveAccountBaseUrl(region);
  const accountEnv = resolveAccountEnvironmentFromAccountBaseUrl(baseUrl);
  if (accountEnv === "local") return "nucleus_local";
  if (accountEnv === "pre") return "nucleus_pre";
  return "nucleus";
}

export async function peformAccountApiCall(
  path: string,
  body: any,
  params?: {
    method?: "POST" | "GET" | "PUT" | "DELETE" | "HEAD";
    region?: string;
    headers?: any;
  }
) {
  const [{ ClientStorageKey }, { clientStorage }] = await Promise.all([
    import("@21n/persistence/persistence.type"),
    import("@21n/persistence/persistence.utils")
  ]);
  const region =
    params?.region ?? (await clientStorage.get(ClientStorageKey.REGION));
  const baseUrl = resolveAccountBaseUrl(region ?? "insouth");
  const method = params?.method ?? "POST";
  const fetchOptions: RequestInit = {
    method,
    headers: {
      "Content-Type": "application/json",
      ...(params?.headers ?? {})
    }
  };

  if (method !== "GET" && method !== "HEAD") {
    fetchOptions.body = JSON.stringify(body);
  }

  return fetch(baseUrl + "/" + path, fetchOptions);
}

function resolveNativeConfigUrl(key: "webOrigin" | "accountUrl") {
  if (typeof window === "undefined") return null;
  const value = window.__NUCLEUM_NATIVE_CONFIG__?.[key];
  if (!value) return null;
  try {
    return new URL(value);
  } catch {
    return null;
  }
}

function resolveNativeAccountBaseUrl(region: string) {
  const nativeConfig = typeof window === "undefined" ? null : window.__NUCLEUM_NATIVE_CONFIG__;
  if (nativeConfig?.environment) {
    const environment = nativeConfig.environment.trim().toLowerCase();
    const normalizedRegion = normalizeAccountRegion(region || nativeConfig.defaultRegion);
    const accountDomain = nativeConfig.accountDomain?.trim() || resolveAccountDomainFromProduct(nativeConfig.product);
    const suffix = environment === "live" ? "" : `-${environment}`;
    return `https://account-${normalizedRegion}${suffix}.${accountDomain}`;
  }

  const nativeAccountUrl = resolveNativeConfigUrl("accountUrl");
  if (!nativeAccountUrl) return null;

  return nativeAccountUrl.toString().replace(/\/$/, "");
}

function renderAccountBaseUrlTemplate(template: string, region: string) {
  const normalizedRegion = normalizeAccountRegion(region);
  const accountEnv = resolveAccountEnvironment();
  const accountDomain = resolveAccountDomain();
  const envSuffix = accountEnv === "live" ? "" : `-${accountEnv}`;

  return template
    .replaceAll("{region}", normalizedRegion)
    .replaceAll("{env}", accountEnv)
    .replaceAll("{envSuffix}", envSuffix)
    .replaceAll("{domain}", accountDomain)
    .replace(/\/$/, "");
}

function resolveAccountEnvironmentFromAccountBaseUrl(baseUrl: string): AccountEnvironment {
  try {
    const hostname = new URL(baseUrl).hostname.toLowerCase();
    if (hostname.startsWith("account-") || hostname.includes(".account-")) {
      if (hostname.includes("-local.")) return "local";
      if (hostname.includes("-pre.")) return "pre";
      if (hostname.includes("-dev.")) return "dev";
      return "live";
    }
  } catch {
    // Fall through to the web/native environment resolver.
  }
  return resolveAccountEnvironment();
}

export type AccountEnvironment = "local" | "dev" | "pre" | "live";

export function resolveAccountEnvironment(host = resolveHost()): AccountEnvironment {
  const normalizedHost = host.toLowerCase();
  const subdomain = normalizedHost.split(".")[0] ?? "";
  if (subdomain === "local" || normalizedHost.endsWith(".localhost")) {
    return "local";
  }
  if (subdomain === "dev") {
    return "dev";
  }
  if (subdomain === "pre") {
    return "pre";
  }
  if (subdomain === "web" || subdomain === "app") {
    return "live";
  }

  const configured = (import.meta.env?.VITE_ENV ?? "").trim().toLowerCase();
  if (configured === "pre") {
    return "pre";
  }
  if (configured === "local" || configured === "dev" || configured === "live") {
    return configured;
  }
  return "dev";
}

export function resolveAccountDomain(host = resolveHost()): string {
  const configured = import.meta.env?.VITE_ACCOUNT_DOMAIN?.trim();
  if (configured) return configured.replace(/^\./, "");

  return resolveProductDomainFromHost(host) ?? "nucleum.app";
}

function resolveProductDomainFromHost(host: string): string | null {
  const normalized = host.toLowerCase().replace(/:\d+$/, "");
  if (isLoopbackHost(normalized)) return null;

  const labels = normalized.split(".").filter(Boolean);
  if (labels.length < 2) return null;

  const first = labels[0];
  if (["local", "dev", "pre", "web", "app"].includes(first)) {
    return labels.slice(1).join(".");
  }

  if (first.startsWith("account-")) {
    return labels.slice(1).join(".");
  }

  return labels.slice(-2).join(".");
}

function resolveAccountDomainFromProduct(product: string | undefined): string {
  const normalized = product?.trim().toLowerCase().replace(/^\./, "");
  return normalized || "nucleum.app";
}

function normalizeAccountRegion(region: string | undefined): string {
  return region?.trim().toLowerCase() || "insouth";
}

function isLoopbackHost(host: string): boolean {
  return host === "localhost" || host === "127.0.0.1" || host === "0.0.0.0";
}

