#!/usr/bin/env node

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import {
  isMain,
  portablePath,
  productionIssuer,
  productionResource,
  publicTurnstileSiteKey,
  requireHyperdriveId,
  root,
  sha256,
  workers,
  writeJsonAtomic,
} from "./lib/production-deployment.mjs";

const templateDirectory = resolve(root, "deployment", "wrangler");

async function readTemplate(name) {
  return JSON.parse(
    await readFile(resolve(templateDirectory, `${name}.production.json`), "utf8"),
  );
}

function runtimeConfig(template, hyperdriveId, variables = {}) {
  return {
    ...template,
    hyperdrive: [{ binding: "HYPERDRIVE", id: hyperdriveId }],
    vars: {
      ...template.vars,
      ...variables,
    },
  };
}

function validateRenderedConfig(name, config, hyperdriveId) {
  const serialized = JSON.stringify(config);
  const route = config.routes?.[0];
  const routeIsValid =
    route?.pattern === workers[name].host && route.custom_domain === true;
  if (
    config.name !== workers[name].name ||
    config.workers_dev !== false ||
    config.routes?.length !== 1 ||
    !routeIsValid ||
    /placeholder|replace[-_ ]?me|your[-_ ]?(?:id|key|token)/iu.test(serialized)
  ) {
    throw new Error(`The ${name} production template violates the deployment contract`);
  }
  if (
    config.hyperdrive?.length !== 1 ||
    config.hyperdrive[0]?.binding !== "HYPERDRIVE" ||
    config.hyperdrive[0]?.id !== hyperdriveId ||
    config.r2_buckets?.[0]?.bucket_name !== "skillplane-skill-bundles"
  ) {
    throw new Error(`The ${name} production binding inventory is incomplete`);
  }
  if (
    config.vars?.OAUTH_ISSUER !== productionIssuer ||
    config.vars?.OAUTH_RESOURCE !== productionResource
  ) {
    throw new Error(`The ${name} production OAuth identity is not canonical`);
  }
  if (
    name === "app" &&
    (config.send_email?.[0]?.name !== "SEND_EMAIL" || config.vars?.AUTH_MODE !== "otp")
  ) {
    throw new Error("The app production email binding is incomplete");
  }
  if (
    name === "mcp" &&
    (config.send_email !== undefined ||
      !config.rules?.some(
        (rule) =>
          rule.type === "Data" &&
          rule.globs?.includes("**/*.png") &&
          rule.globs?.includes("**/*.ico"),
      ) ||
      "AUTH_MODE" in (config.vars ?? {}) ||
      "EMAIL_PROVIDER" in (config.vars ?? {}) ||
      "PUBLIC_TURNSTILE_SITE_KEY" in (config.vars ?? {}) ||
      "TURNSTILE_ALLOWED_HOSTNAMES" in (config.vars ?? {}) ||
      "SKILLPLANE_OTP_FROM" in (config.vars ?? {}))
  ) {
    throw new Error("The MCP Worker must not receive an email binding");
  }
}

export async function renderDeploymentConfigs(options = {}) {
  const hyperdriveId = requireHyperdriveId(options.hyperdriveId);
  const siteKey = options.siteKey ?? publicTurnstileSiteKey();
  const templates = {
    app: runtimeConfig(await readTemplate("app"), hyperdriveId, {
      PUBLIC_TURNSTILE_SITE_KEY: siteKey,
    }),
    mcp: runtimeConfig(await readTemplate("mcp"), hyperdriveId),
  };
  for (const config of Object.values(templates)) {
    config.$schema = "../node_modules/wrangler/config-schema.json";
  }
  for (const [name, config] of Object.entries(templates)) {
    validateRenderedConfig(name, config, hyperdriveId);
  }
  if (options.write !== false) {
    for (const [name, config] of Object.entries(templates)) {
      await writeJsonAtomic(
        options.outputPaths?.[name] ?? workers[name].config,
        config,
        { mode: 0o600 },
      );
    }
  }
  return {
    ok: true,
    hyperdriveId,
    configs: Object.fromEntries(
      Object.entries(templates).map(([name, config]) => [
        name,
        {
          path: portablePath(options.outputPaths?.[name] ?? workers[name].config),
          sha256: sha256(JSON.stringify(config)),
          worker: config.name,
          host: workers[name].host,
          routing: {
            type: "custom-domain",
            pattern: config.routes[0].pattern,
          },
        },
      ]),
    ),
  };
}

if (isMain(import.meta.url)) {
  const result = await renderDeploymentConfigs();
  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
}
#!/usr/bin/env node

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import {
  deployNamedWorker,
  ensureCloudflareSession,
  ensureProductionBucket,
  verifyProductionHyperdrive,
} from "./lib/cloudflare-production.mjs";
import {
  assertRecentDatabaseSafetyState,
  capture,
  isMain,
  portablePath,
  productionReleaseTag,
  productionSecrets,
  requireCleanSourceRevision,
  requireHyperdriveId,
  root,
  run,
  sanitizeDeploymentRecord,
  sha256,
  writeJsonAtomic,
} from "./lib/production-deployment.mjs";
import { productionSmoke } from "./production-smoke.mjs";
import { renderDeploymentConfigs } from "./render-deploy-config.mjs";

async function releaseSourceDigest() {
  const files = new Set([
    "package.json",
    "pnpm-lock.yaml",
    "pnpm-workspace.yaml",
    "turbo.json",
    "tsconfig.base.json",
  ]);
  const listed = capture("rg", [
    "--files",
    "app",
    "mcp",
    "packages",
    "scripts",
    "deployment",
  ]);
  for (const path of listed.stdout?.split("\n") ?? []) {
    if (path) files.add(path);
  }
  const source = await Promise.all(
    [...files]
      .sort()
      .map(async (path) => [path, sha256(await readFile(resolve(root, path)))]),
  );
  return sha256(JSON.stringify(source));
}

export async function deployAll() {
  const startedAt = new Date().toISOString();
  const tag = productionReleaseTag();

  // Resolve every local prerequisite before the first Cloudflare mutation.
  const hyperdriveId = requireHyperdriveId();
  productionSecrets();
  const database = await assertRecentDatabaseSafetyState();
  const sourceRevision = requireCleanSourceRevision();
  const sourceDigest = await releaseSourceDigest();
  const rendered = await renderDeploymentConfigs();
  ensureCloudflareSession();
  const hyperdrive = verifyProductionHyperdrive(database.database.identity);
  run("pnpm", ["build"], { failureMessage: "Production monorepo build failed" });

  const r2 = ensureProductionBucket();
  const progressPath = resolve(root, ".data", "production", "release-in-progress.json");
  const workerDeployments = {};
  for (const kind of ["app", "mcp"]) {
    workerDeployments[kind] = await deployNamedWorker(kind, {
      build: false,
      tag,
    });
    await writeJsonAtomic(
      progressPath,
      sanitizeDeploymentRecord({
        ok: false,
        startedAt,
        tag,
        completedWorkers: Object.keys(workerDeployments),
        workers: workerDeployments,
      }),
      { mode: 0o600 },
    );
  }
  const smoke = await productionSmoke({ attempts: 90 });
  const finalSourceRevision = requireCleanSourceRevision();
  const finalSourceDigest = await releaseSourceDigest();
  if (
    finalSourceRevision.commit !== sourceRevision.commit ||
    finalSourceDigest !== sourceDigest
  ) {
    throw new Error("Skillplane source changed during production deployment");
  }
  const manifest = sanitizeDeploymentRecord({
    schemaVersion: 1,
    ok: true,
    environment: "production",
    startedAt,
    completedAt: new Date().toISOString(),
    tag,
    applicationCommit: sourceRevision.commit,
    sourceDigest,
    topology: {
      databaseOrigin: "postgresql",
      workerDatabasePath: "cloudflare-hyperdrive",
      runtimeDirectDatabaseUrl: false,
      hosts: {
        landing: "https://skillplane.dev",
