        kind: "oauth",
        actorType: "user",
        actorId: verified.userId,
        userId: verified.userId,
        credentialId: verified.tokenId,
        credentialKind: "oauth_access_token",
        clientId: verified.clientId,
        scopes: verified.scopes,
