  const challenge = protectedResourceChallenge(runtime, {
    error: error.status === 403 ? "insufficient_scope" : "invalid_token",
    ...(error.scopes.length > 0 ? { scopes: error.scopes } : {}),
  });
  return new Response(
    JSON.stringify({
