 10	export function enforceCookieCsrf(
 11	  request: Request,
 12	  hasSession: boolean,
 13	  hasServicePrincipal: boolean,
 14	): void {
 15	  const url = new URL(request.url);
 16	  if (
 17	    !hasSession ||
 18	    hasServicePrincipal ||
 19	    SAFE_METHODS.has(request.method) ||
 20	    !url.pathname.startsWith("/api/v1/")
 21	  ) {
 22	    return;
 23	  }
 24	  const cookie = request.headers.get("cookie") ?? "";
 25	  const bearerWithoutSessionCookie =
 26	    request.headers.get("authorization")?.startsWith("Bearer ") === true &&
 27	    !cookie
 28	      .split(";")
 29	      .some((entry) => entry.trim().startsWith(`${AUTH_SESSION_COOKIE}=`));
 30	  if (bearerWithoutSessionCookie) return;
 31	  const cookieToken = readCsrfToken(request.headers.get("cookie"));
 32	  const headerToken = request.headers.get(AUTH_CSRF_HEADER);
 33	  if (!cookieToken || !headerToken || cookieToken !== headerToken) {
 34	    throw new DomainError(
 35	      "AUTH_CSRF_INVALID",
 36	      "The request could not be verified",
 37	      403,
 38	    );
 39	  }
 40	}
