 42	export function authenticationMiddleware(
 43	  getServices?: ApiServiceProvider,
 44	): MiddlewareHandler<ApiEnvironment> {
 45	  return async (context, next) => {
 46	    if (!getServices || context.req.path.startsWith("/api/v1/health/")) {
 47	      context.set("services", null);
 48	      context.set("session", null);
 49	      context.set("servicePrincipal", null);
 50	      await next();
 51	      return;
 52	    }
 53	    const services = await getServices(context.env);
 54	    try {
 55	      context.set("services", services);
 56	      const serviceAuthentication = await authenticateServicePrincipalRequest(
 57	        context.req.raw,
 58	        services,
 59	      );
 60	      const servicePrincipal = serviceAuthentication?.principal ?? null;
 61	      context.set("servicePrincipal", servicePrincipal);
 62	      const session = servicePrincipal
 63	        ? null
 64	        : await services.auth.provider.authenticate(context.req.raw);
 65	      context.set("session", session);
 66	      if (session) {
 67	        await ensurePersonalWorkspace(services.database.pool, session);
 68	      }
 69	      enforceCookieCsrf(context.req.raw, Boolean(session), Boolean(servicePrincipal));
 70	      await next();
 71	    } finally {
 72	      try {
 73	        await getServices.release?.(services);
 74	      } catch {
 75	        console.error(
 76	          JSON.stringify({
 77	            component: "api",
 78	            event: "api.services.release.failed",
 79	          }),
 80	        );
 81	      }
 82	    }
 83	  };
 84	}
