 37	export class AuthClientError extends Error {
 38	  readonly code: string;
 39	  readonly requestId?: string;
 40	  readonly retryable: boolean;
 41	  readonly status: number;
 42	
 43	  constructor(
 44	    status: number,
 45	    code: string,
 46	    message: string,
 47	    retryable: boolean,
 48	    requestId?: string,
 49	  ) {
 50	    super(message);
 51	    this.name = "AuthClientError";
 52	    this.status = status;
 53	    this.code = code;
 54	    this.retryable = retryable;
 55	    if (requestId) this.requestId = requestId;
