 24	async function stablePersonalSlug(userId: string): Promise<string> {
 25	  const digest = await crypto.subtle.digest(
 26	    "SHA-256",
 27	    new TextEncoder().encode(userId),
 28	  );
 29	  const suffix = [...new Uint8Array(digest)]
 30	    .slice(0, 10)
 31	    .map((byte) => byte.toString(16).padStart(2, "0"))
 32	    .join("");
 33	  return `personal-${suffix}`;
 34	}
