122	export async function lockWorkspaceMemberships(
123	  client: PoolClient,
124	  workspaceId: string,
125	): Promise<readonly MembershipRow[]> {
126	  const result = await client.query<MembershipRow>(
127	    `SELECT m.id, m.role, m.user_id, m.workspace_id, u.primary_email AS email,
128	            u.metadata->>'displayName' AS display_name
129	       FROM workspace_memberships m
130	       JOIN authfn_users u ON u.id = m.user_id
131	      WHERE m.workspace_id = $1
132	      ORDER BY m.created_at, m.id
133	      FOR UPDATE OF m`,
134	    [workspaceId],
135	  );
136	  return result.rows;
