 18	const templateDirectory = resolve(root, "deployment", "wrangler");
 19	
 20	async function readTemplate(name) {
 21	  return JSON.parse(
 22	    await readFile(resolve(templateDirectory, `${name}.production.json`), "utf8"),
 23	  );
 24	}
 25	
 26	function runtimeConfig(template, hyperdriveId, variables = {}) {
 27	  return {
 28	    ...template,
 29	    hyperdrive: [{ binding: "HYPERDRIVE", id: hyperdriveId }],
 30	    vars: {
 31	      ...template.vars,
 32	      ...variables,
 33	    },
 34	  };
 35	}
 36	
 37	function validateRenderedConfig(name, config, hyperdriveId) {
 38	  const serialized = JSON.stringify(config);
 39	  const route = config.routes?.[0];
 40	  const routeIsValid =
 41	    route?.pattern === workers[name].host && route.custom_domain === true;
 42	  if (
 43	    config.name !== workers[name].name ||
 44	    config.workers_dev !== false ||
 45	    config.routes?.length !== 1 ||
 46	    !routeIsValid ||
 47	    /placeholder|replace[-_ ]?me|your[-_ ]?(?:id|key|token)/iu.test(serialized)
 48	  ) {
 49	    throw new Error(`The ${name} production template violates the deployment contract`);
 50	  }
 51	  if (
 52	    config.hyperdrive?.length !== 1 ||
 53	    config.hyperdrive[0]?.binding !== "HYPERDRIVE" ||
 54	    config.hyperdrive[0]?.id !== hyperdriveId ||
 55	    config.r2_buckets?.[0]?.bucket_name !== "skillplane-skill-bundles"
 56	  ) {
 57	    throw new Error(`The ${name} production binding inventory is incomplete`);
 58	  }
 59	  if (
 60	    config.vars?.OAUTH_ISSUER !== productionIssuer ||
 61	    config.vars?.OAUTH_RESOURCE !== productionResource
 62	  ) {
 63	    throw new Error(`The ${name} production OAuth identity is not canonical`);
 64	  }
 65	  if (
 66	    name === "app" &&
 67	    (config.send_email?.[0]?.name !== "SEND_EMAIL" || config.vars?.AUTH_MODE !== "otp")
 68	  ) {
 69	    throw new Error("The app production email binding is incomplete");
 70	  }
 71	  if (
 72	    name === "mcp" &&
 73	    (config.send_email !== undefined ||
 74	      !config.rules?.some(
 75	        (rule) =>
 76	          rule.type === "Data" &&
 77	          rule.globs?.includes("**/*.png") &&
 78	          rule.globs?.includes("**/*.ico"),
 79	      ) ||
 80	      "AUTH_MODE" in (config.vars ?? {}) ||
 81	      "EMAIL_PROVIDER" in (config.vars ?? {}) ||
 82	      "PUBLIC_TURNSTILE_SITE_KEY" in (config.vars ?? {}) ||
 83	      "TURNSTILE_ALLOWED_HOSTNAMES" in (config.vars ?? {}) ||
 84	      "SKILLPLANE_OTP_FROM" in (config.vars ?? {}))
 85	  ) {
 86	    throw new Error("The MCP Worker must not receive an email binding");
 87	  }
 88	}
 89	
 90	export async function renderDeploymentConfigs(options = {}) {
 91	  const hyperdriveId = requireHyperdriveId(options.hyperdriveId);
 92	  const siteKey = options.siteKey ?? publicTurnstileSiteKey();
 93	  const templates = {
 94	    app: runtimeConfig(await readTemplate("app"), hyperdriveId, {
 95	      PUBLIC_TURNSTILE_SITE_KEY: siteKey,
 96	    }),
 97	    mcp: runtimeConfig(await readTemplate("mcp"), hyperdriveId),
 98	  };
 99	  for (const config of Object.values(templates)) {
100	    config.$schema = "../node_modules/wrangler/config-schema.json";
101	  }
102	  for (const [name, config] of Object.entries(templates)) {
103	    validateRenderedConfig(name, config, hyperdriveId);
104	  }
105	  if (options.write !== false) {
106	    for (const [name, config] of Object.entries(templates)) {
107	      await writeJsonAtomic(
108	        options.outputPaths?.[name] ?? workers[name].config,
109	        config,
110	        { mode: 0o600 },
111	      );
112	    }
113	  }
114	  return {
115	    ok: true,
116	    hyperdriveId,
117	    configs: Object.fromEntries(
118	      Object.entries(templates).map(([name, config]) => [
119	        name,
120	        {
121	          path: portablePath(options.outputPaths?.[name] ?? workers[name].config),
122	          sha256: sha256(JSON.stringify(config)),
123	          worker: config.name,
124	          host: workers[name].host,
125	          routing: {
126	            type: "custom-domain",
127	            pattern: config.routes[0].pattern,
128	          },
129	        },
130	      ]),
131	    ),
132	  };
133	}
134	
135	if (isMain(import.meta.url)) {
136	  const result = await renderDeploymentConfigs();
137	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
138	}

