184	export async function closeApiServices(services: ApiServices): Promise<void> {
185	  let firstError: unknown;
186	  const close = async (operation: () => Promise<void>): Promise<void> => {
187	    try {
188	      await operation();
189	    } catch (error) {
190	      firstError ??= error;
191	    }
192	  };
193	
194	  await close(() => services.datafn.close());
195	  const email = services.email;
196	  if (email) {
197	    await close(() => email.close());
198	  }
199	  await close(() => services.database.close());
