 18	const templateDirectory = resolve(root, "deployment", "wrangler");
 19	
 20	async function readTemplate(name) {
 21	  return JSON.parse(
 22	    await readFile(resolve(templateDirectory, `${name}.production.json`), "utf8"),
 23	  );
 24	}
