    89	export async function requireUserPrincipal(
    90	  pool: Pool,
    91	  session: AuthFnSession | null,
    92	  workspaceId: string,
    93	): Promise<UserPrincipal> {
    94	  if (!session) {
    95	    throw new DomainError("AUTHENTICATION_REQUIRED", "A user session is required", 401);
    96	  }
    97	  const result = await pool.query<MembershipRow>(
    98	    `SELECT m.id, m.role, m.user_id, m.workspace_id, u.primary_email AS email,
    99	            u.metadata->>'displayName' AS display_name
   100	       FROM workspace_memberships m
   101	       JOIN authfn_users u ON u.id = m.user_id
   102	      WHERE m.workspace_id = $1 AND m.user_id = $2
   103	      LIMIT 1`,
   104	    [workspaceId, session.actorId],
   105	  );
   106	  const membership = result.rows[0];
   107	  if (!membership || !isWorkspaceRole(membership.role)) {
   108	    throw new WorkspaceAccessError();
   109	  }
   110	  return {
   111	    kind: "user",
   112	    actorId: membership.user_id,
   113	    userId: membership.user_id,
   114	    sessionId: session.id,
   115	    workspaceId: membership.workspace_id,
   116	    role: membership.role,
   117	    ...(membership.email ? { email: membership.email } : {}),
   118	    ...(membership.display_name ? { displayName: membership.display_name } : {}),
   119	  };
   120	}
