     9	import type { Pool, PoolClient } from "pg";
    10	
    11	interface MembershipRow {
    12	  readonly id: string;
    13	  readonly role: string;
    14	  readonly user_id: string;
    15	  readonly workspace_id: string;
    16	  readonly email: string | null;
