    20	function id(prefix: string): string {
    21	  return `${prefix}:${crypto.randomUUID()}`;
    22	}
    23	
    24	async function stablePersonalSlug(userId: string): Promise<string> {
    25	  const digest = await crypto.subtle.digest(
    26	    "SHA-256",
    27	    new TextEncoder().encode(userId),
    28	  );
    29	  const suffix = [...new Uint8Array(digest)]
    30	    .slice(0, 10)
    31	    .map((byte) => byte.toString(16).padStart(2, "0"))
    32	    .join("");
    33	  return `personal-${suffix}`;
    34	}
    35	
    36	export async function ensurePersonalWorkspace(
    37	  pool: Pool,
    38	  session: AuthFnSession,
    39	): Promise<string> {
    40	  const client = await pool.connect();
    41	  try {
    42	    await client.query("BEGIN");
    43	    await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [
    44	      session.actorId,
    45	    ]);
    46	    const existing = await client.query<{ id: string }>(
    47	      `SELECT id FROM workspaces
    48	        WHERE kind = 'personal' AND personal_owner_user_id = $1
    49	        LIMIT 1`,
    50	      [session.actorId],
    51	    );
    52	    let workspaceId = existing.rows[0]?.id;
    53	    if (!workspaceId) {
    54	      workspaceId = id("workspace");
    55	      const email =
    56	        typeof session.subject.email === "string" ? session.subject.email : undefined;
    57	      const label = email?.split("@")[0]?.trim();
    58	      await client.query(
    59	        `INSERT INTO workspaces
    60	           (id, workspace_id, slug, name, kind, created_by_user_id,
    61	            personal_owner_user_id)
    62	         VALUES ($1, $1, $2, $3, 'personal', $4, $4)`,
    63	        [
    64	          workspaceId,
    65	          await stablePersonalSlug(session.actorId),
    66	          label ? `${label}'s workspace` : "Personal workspace",
    67	          session.actorId,
    68	        ],
    69	      );
    70	    }
    71	    await client.query(
    72	      `INSERT INTO workspace_memberships
    73	         (id, workspace_id, user_id, role)
    74	       VALUES ($1, $2, $3, 'owner')
    75	       ON CONFLICT (workspace_id, user_id)
    76	       DO UPDATE SET role = 'owner', updated_at = now()`,
    77	      [id("membership"), workspaceId, session.actorId],
    78	    );
    79	    await client.query("COMMIT");
    80	    return workspaceId;
    81	  } catch (error) {
    82	    await client.query("ROLLBACK");
    83	    throw error;
    84	  } finally {
    85	    client.release();
    86	  }
    87	}
