 27	export async function verifyAccessToken(
 28	  runtime: OAuthRuntime,
 29	  token: string,
 30	  options: {
 31	    readonly resource: string;
 32	    readonly requiredScopes?: readonly string[];
 33	  },
 34	): Promise<VerifiedOAuthPrincipal> {
 35	  if (!token.startsWith("spo_") || token.length > 512) {
 36	    throw new OAuthError("invalid_grant", "The access token is invalid", 401);
 37	  }
 38	  const result = await runtime.pool.query<AccessTokenRow>(
 39	    `SELECT t.id, t.user_id, t.client_id, t.resource, t.scopes, t.expires_at,
 40	            t.revoked_at
 41	       FROM authfn_oauth_access_tokens t
 42	       JOIN authfn_users u ON u.id = t.user_id
 43	      WHERE t.token_hash = $1
 44	      LIMIT 1`,
 45	    [keyedHash(token, runtime.tokenPepper)],
 46	  );
 47	  const row = result.rows[0];
 48	  if (
 49	    !row ||
 50	    row.revoked_at ||
 51	    row.expires_at.getTime() <= runtime.now().getTime() ||
 52	    row.resource !== options.resource ||
 53	    options.requiredScopes?.some((scope) => !row.scopes.includes(scope))
 54	  ) {
 55	    throw new OAuthError("invalid_grant", "The access token is invalid", 401);
 56	  }
 57	  return {
 58	    kind: "oauth-user",
 59	    actorType: "user",
 60	    actorId: row.user_id,
 61	    userId: row.user_id,
 62	    clientId: row.client_id,
 63	    tokenId: row.id,
 64	    resource: row.resource,
 65	    scopes: row.scopes,
 66	    expiresAt: row.expires_at,
 67	  };
 68	}
