 64	  init: RequestInit = {},
 65	): Promise<SuccessEnvelope<T>> {
 66	  let response: Response;
 67	  try {
 68	    const headers = new Headers(init.headers);
 69	    headers.set("accept", "application/json");
 70	    if (init.body) headers.set("content-type", "application/json");
 71	    response = await fetch(path, {
 72	      ...init,
 73	      credentials: "include",
 74	      headers,
 75	    });
 76	  } catch {
 77	    throw new AuthClientError(
 78	      0,
 79	      "AUTH_NETWORK_ERROR",
 80	      "We could not reach Skillplane. Check your connection and try again.",
 81	      true,
 82	    );
 83	  }
 84	
 85	  let body: SuccessEnvelope<T> | ErrorEnvelope;
 86	  try {
 87	    body = (await response.json()) as SuccessEnvelope<T> | ErrorEnvelope;
 88	  } catch {
 89	    throw new AuthClientError(
 90	      response.status,
 91	      "AUTH_RESPONSE_INVALID",
 92	      "Authentication is temporarily unavailable.",
 93	      true,
 94	    );
 95	  }
 96	  if (!response.ok || !body.ok) {
 97	    const error = body.ok ? undefined : body.error;
 98	    throw new AuthClientError(
