152	    kv('AUTHFN_COOKIE_SECURE', 'true'),
153	    kv('ACCOUNT_LATENCY_DEBUG', String(envConfig.latencyDebug === true)),
154	    kv('DEBUG_SINK_URL', config.debugSinkUrl),
155	    kv('ACCOUNT_REGION_ID', regionId),
156	    kv('ACCOUNT_AUTHORITY', accountAuthority(config, environment, regionId)),
157	    kv('ACCOUNT_COOKIE_DOMAIN', cookieDomainForProductDomain(config.accountDomain)),
158	    kv('ACCOUNT_CORS_ORIGINS', corsOrigins.join(',')),
159	    kv('ACCOUNT_REGIONS_JSON', JSON.stringify(regionRecords)),
