 19	export function renderConfig(config, environment, options = {}) {
 20	  const includeRoutes = options.includeRoutes === true;
 21	  const envConfig = readEnvironment(config, environment);
 22	  const lines = [
 23	    kv('name', config.workerNamePrefix ?? 'nucleus-account'),
 24	    kv('main', config.main ?? 'dist/worker.js'),
 25	    kv('compatibility_date', config.compatibilityDate ?? '2026-04-24'),
 26	    array('compatibility_flags', config.compatibilityFlags ?? ['nodejs_compat']),
 27	    kv('workers_dev', true),
 28	    '',
 29	    '[vars]',
 30	    kv('NODE_ENV', 'production'),
 31	    ''
 32	  ];
 33	
 34	  for (const lookupEnv of lookupEnvironments(config, environment)) {
 35	    lines.push(...renderLookupEnvironment(config, lookupEnv), '');
 36	  }
 37	
 38	  for (const regionId of Object.keys(config.regions)) {
 39	    if (!envConfig.regions[regionId]) continue;
 40	    lines.push(...renderRegionalEnvironment(config, environment, regionId, { includeRoutes }), '');
 41	  }
 42	
 43	  return `${lines.join('\n').trimEnd()}\n`;
 44	}
