  4	export function renderWranglerConfig(serviceRoot, config, environment, options = {}) {
  5	  const includeRoutes = options.includeRoutes === true;
  6	  const outputDir = path.join(serviceRoot, '.wrangler');
  7	  fs.mkdirSync(outputDir, { recursive: true });
  8	  const generatedConfig = {
  9	    ...config,
 10	    main: toPosixPath(path.relative(outputDir, path.join(serviceRoot, config.main ?? 'dist/worker.js')))
 11	  };
 12	  const source = renderConfig(generatedConfig, environment, { includeRoutes });
 13	  const suffix = includeRoutes ? 'with-routes' : 'deploy';
 14	  const outputPath = path.join(outputDir, `wrangler.${environment}.${suffix}.toml`);
 15	  fs.writeFileSync(outputPath, source);
 16	  return outputPath;
 17	}
