 46	export function routeDefinitions(config, environment, regions = Object.keys(config.regions)) {
 47	  const envConfig = readEnvironment(config, environment);
 48	  return regions.flatMap((regionId) => {
 49	    const regionConfig = envConfig.regions[regionId];
 50	    if (!regionConfig) {
 51	      throw new Error(`Unknown ${environment} region: ${regionId}`);
 52	    }
 53	    return productDomains(config).map((domain) => ({
 54	      pattern: `${accountHost(config, environment, regionId, domain)}/*`,
 55	      script: workerName(config, environment, regionId),
 56	      zoneName: domain
 57	    }));
 58	  });
 59	}
