 61	export function missingHyperdriveIds(config, environment, regions) {
 62	  const envConfig = readEnvironment(config, environment);
 63	  const missing = [];
 64	  for (const region of regions) {
 65	    const regionConfig = envConfig.regions[region];
 66	    if (!regionConfig) {
 67	      missing.push(`${environment}/${region}: missing region config`);
 68	      continue;
 69	    }
 70	    for (const binding of hyperdriveBindings()) {
 71	      const configuredValue = regionConfig[binding.configKey];
 72	      const value = resolveHyperdriveId(environment, region, configuredValue, binding.kind);
 73	      if (isPlaceholder(value)) {
 74	        missing.push(`${environment}/${region}/${binding.name}: set ${hyperdriveOverrideName(environment, region, configuredValue, binding.kind)} or update services/account/config/environments.json`);
 75	      }
 76	    }
 77	  }
 78	  return missing;
 79	}
