310	async function saveRegion(
311	  storage: AuthFnRegionStorage,
312	  cacheTtlMs: number,
313	  options: AuthFnRegionalClientOptions,
314	  region: AuthFnCachedRegion,
315	  fromRegionId?: string
316	): Promise<void> {
