331	function regionFromMismatch(
332	  identifier: string,
333	  response: unknown,
334	  cacheTtlMs: number
335	): AuthFnCachedRegion | null {
336	  if (!response || typeof response !== 'object') {
337	    return null;
338	  }
339	
340	  const envelope = response as AuthFnErrorEnvelope;
341	  if (envelope.ok !== false || envelope.error.code !== 'AUTHFN_REGION_MISMATCH') {
342	    return null;
343	  }
344	
345	  const details = envelope.error.details ?? {};
346	  const regionId = typeof details.regionId === 'string' ? details.regionId : undefined;
347	  const authority = typeof details.authority === 'string'
348	    ? details.authority
349	    : typeof details.redirectTo === 'string'
350	      ? details.redirectTo
351	      : undefined;
352	  if (!regionId || !authority) {
353	    return null;
354	  }
355	
356	  return {
357	    identifier,
358	    regionId,
359	    authority,
360	    domain: typeof details.domain === 'string' ? details.domain : undefined,
361	    cachedAt: Date.now(),
362	    expiresAt: Date.now() + cacheTtlMs
363	  };
364	}
