113	export async function lookupRegionByIdentifier(
114	  config: Pick<AuthFnRuntimeConfig, 'database' | 'stores' | 'namespace' | 'plugins'>,
115	  pluginConfig: MultiRegionPluginRuntimeConfig,
116	  input: {
117	    identifier: string;
118	    request?: Request;
119	    environment: AuthFnEnvironment;
120	    bypassCache?: boolean;
121	  }
122	): Promise<AuthFnRegionLookup | null> {
123	  const identifier = normalizeIdentifier(input.identifier);
124	  const cacheKey = createAuthFnCacheKey(config, 'region', identifier);
125	  if (!input.bypassCache) {
126	    const cached = await getCachedJson<CachedRegionLookup>(getAuthFnCacheStore(config), cacheKey);
127	    if (cached) {
128	      return cached.found ? cached.lookup : null;
129	    }
130	  }
131	
132	  if (pluginConfig.lookupStore) {
133	    const record = await readLookupStoreRecord(pluginConfig.lookupStore, identifier);
134	    if (record) {
135	      const lookup = lookupFromRecord(record);
136	      await setCachedJson(getAuthFnCacheStore(config), {
137	        key: cacheKey,
138	        value: {
139	          found: true,
140	          lookup
141	        } satisfies CachedRegionLookup,
142	        ttlSeconds: AUTHFN_CACHE_TTL_SECONDS.regionHit
143	      });
144	      return lookup;
145	    }
146	  }
147	
148	  const user = await findUserByPrimaryEmail(config, identifier);
149	  if (!user) {
150	    await setCachedJson(getAuthFnCacheStore(config), {
151	      key: cacheKey,
152	      value: {
153	        found: false
154	      } satisfies CachedRegionLookup,
155	      ttlSeconds: AUTHFN_CACHE_TTL_SECONDS.regionMiss
156	    });
157	    return null;
158	  }
159	
160	  const profile = await findRegionProfileByUserId(config, user.id);
161	  if (!profile) {
162	    await setCachedJson(getAuthFnCacheStore(config), {
163	      key: cacheKey,
164	      value: {
165	        found: false
166	      } satisfies CachedRegionLookup,
167	      ttlSeconds: AUTHFN_CACHE_TTL_SECONDS.regionMiss
168	    });
169	    return null;
170	  }
171	
172	  const lookup = {
173	    userId: user.id,
174	    regionId: profile.regionId,
175	    authority: profile.authority,
176	    domain: profile.domain ?? undefined
177	  };
178	  await setCachedJson(getAuthFnCacheStore(config), {
179	    key: cacheKey,
180	    value: {
190	  config: Pick<AuthFnRuntimeConfig, 'database' | 'stores' | 'namespace' | 'plugins'>,
191	  pluginConfig: MultiRegionPluginRuntimeConfig,
192	  input: {
193	    identifier: string;
194	    request?: Request;
195	    environment: AuthFnEnvironment;
196	  }
197	): Promise<AuthFnRegionLookupResult> {
198	  const identifier = normalizeIdentifier(input.identifier);
199	  const lookup = await lookupRegionByIdentifier(config, pluginConfig, {
200	    ...input,
201	    identifier
202	  });
203	  if (!lookup) {
204	    return {
205	      identifier,
206	      regionId: input.environment.regionId ?? pluginConfig.defaultRegionId ?? 'unknown',
207	      authority: normalizeAuthority(input.environment.baseUrl),
208	      domain: undefined,
209	      continueLocally: true,
210	      redirectTo: undefined
211	    };
212	  }
213	
214	  const currentRegionId = input.environment.regionId ?? pluginConfig.defaultRegionId;
215	  const currentAuthority = normalizeAuthority(input.environment.baseUrl);
216	  const targetAuthority = resolveLookupAuthorityForRequest(pluginConfig, lookup, input.request, input.environment);
217	  const continueLocally = lookup.regionId === currentRegionId || currentAuthority === targetAuthority;
218	
219	  return {
220	    identifier,
221	    userId: lookup.userId,
222	    regionId: lookup.regionId,
223	    authority: targetAuthority,
224	    domain: lookup.domain,
225	    continueLocally,
226	    redirectTo: continueLocally ? undefined : targetAuthority
227	  };
228	}

